"""docs/RESULTS.md: the paper's tables next to ours. Filled in once runs exist."""

from __future__ import annotations

import json
from pathlib import Path

from .score import score_all


def _pct(rows: list[dict], criterion: str) -> str:
    vals = [r["ratings"][criterion] for r in rows if r["ratings"].get(criterion) is not None]
    return f"{sum(vals) / len(vals):.0%}" if vals else "–"


def write_report(runs_root: Path, questions: dict[str, dict], out: Path) -> Path:
    res = score_all(runs_root, questions)
    lines = [
        "# Results",
        "",
        "Generated by `nav report`. Accuracy over all repeats; n = calls.",
        "",
    ]
    for model, r in res.items():
        lines.append(f"## {model}")
        lines.append("")
        lines.append("| task | questions | n | accuracy |")
        lines.append("|---|---|---|---|")
        for t, v in r["by_task"].items():
            lines.append(f"| {t} | {v['questions']} | {v['n']} | {v['accuracy']:.1%} |")
        lines.append("")
    judged = Path(runs_root) / "judged.jsonl"
    if judged.exists():
        rows = [json.loads(line) for line in judged.read_text().splitlines() if line.strip()]
        by: dict[str, list] = {}
        for r in rows:
            by.setdefault(r["model"], []).append(r)
        lines += [
            "## Navigation (LLM judge, three criteria)",
            "",
            "| model | outputs | destination | route | obstacles |",
            "|---|---|---|---|---|",
        ]
        for model, rs in by.items():
            cells = [_pct(rs, c) for c in ("destination", "route", "obstacles")]
            lines.append(f"| {model} | {len(rs)} | {cells[0]} | {cells[1]} | {cells[2]} |")
        lines.append("")
    out = Path(out)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(lines) + "\n")
    return out
